 if(row.checks)html+='<div class="pari-list">'+Object.entries(row.checks).map(([k,v])=>'<p>'+escape(k.replace(/_/g,' '))+': '+(v?'Verified':'Pending')+'</p>').join('')+'</div>';
 if(row.photo_ids?.length)html+='<div class="evidence-grid">'+row.photo_ids.map(photo=>'<a href="/api/files/'+escape(photo)+'" download>Download photo '+escape(photo.slice(-6))+'</a>').join('')+'</div>';
 const cmds=[];const approved=['approved','handed_over','accepted'].includes(row.status);
