 if(['requirements','engineering-reviews','vendor-comparisons','pm-rules','commissioning','modernizations','quotations','work-orders','projects'].includes(key)&&(!approved||key==='projects'&&row.status==='handed_over')){const allowed=key==='quotations'||key==='work-orders'||key==='projects'?(P().permissionContext?.admin||Live.user()?.role==='Customer Viewer'):['Organization Admin','Super Admin (Pari)','Plant Engineer','Reliability Manager','Plant Manager'].includes(Live.user()?.role);if(allowed)cmds.push(button(key==='work-orders'?'Accept completed work':key==='projects'?'Accept handover':'Review / approve',()=>approval(key,row),true));}
 if(['requirements','engineering-reviews','vendor-comparisons','pm-rules','quotations','checklists'].includes(key)&&approved||key==='checklists')cmds.push(button('Create new revision',()=>{const next={...row,revision:String(Number(row.revision||1)+1),status:key==='checklists'?'draft':'draft'};delete next.id;edit(key,null,next);}));
 if(key==='customers'&&can('enquiries')){cmds.push(button('New enquiry',()=>edit('enquiries',null,{customer_id:row.id})),button('Add site',()=>edit('plants',null,{customer_id:row.id})));}
 if(key==='enquiries'){cmds.push(button('Create quotation',()=>edit('quotations',null,{enquiry_id:row.id,customer_id:row.customer_id,title:'Proposal: '+row.title})),button('Create specification',()=>edit('requirements',null,{enquiry_id:row.id,customer_id:row.customer_id,title:row.title})));}
 if(key==='quotations'&&row.status==='approved'&&can('contracts'))cmds.push(button('Create contract',()=>edit('contracts',null,{quotation_id:row.id,customer_id:row.customer_id,title:row.title,fee:row.total})));
