function plantSwitch(){const el=U().dialog('Switch plant','<div class="pari-list">'+P().plants.map(p=>'<button class="pari-list-item" style="text-align:left" data-plant="'+escape(p.id)+'"><strong>'+escape(p.name)+'</strong><p>'+p.crane_count+' cranes · '+escape(p.state)+'</p></button>').join('')+'</div>'+(can('plants')?'<div class="pari-inline-actions"><a class="btn btn-secondary btn-sm" href="plants.html">Manage sites</a></div>':''));el.querySelectorAll('[data-plant]').forEach(button=>button.onclick=()=>{localStorage.setItem('pari.live.'+Live.user().id+'.plant',button.dataset.plant);location.href='dashboard.html';});}
